import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { BLOB_MAX_BYTES, fromHex, toHex } from '@hashtree/core';
import {
  BEP10_EXTENSION,
  MAX_HEADER_BYTES,
  MAX_MESSAGE_BYTES,
  METHOD_CASHU,
  PROTOCOL,
  decodeBencodePrefix,
  decodeReply,
  decodeRequest,
  encodeReply,
  encodeRequest,
  priceMsat,
  type ContentHash,
  type Reply,
  type Request,
} from '../src/index.js';

/** Generated by `rust/crates/hashtree-paid-retrieval/tests/vectors.rs`. */
const VECTORS = JSON.parse(readFileSync(
  new URL('../../../../test-vectors/paid-retrieval-vectors.json', import.meta.url),
  'utf8',
)) as VectorFile;

type Json = Record<string, unknown>;
type WirePart = string | { repeat: string; times: number };

interface VectorFile {
  protocol: string;
  bep10_extension: string;
  method_cashu: string;
  max_header_bytes: number;
  max_message_bytes: number;
  blob_max_bytes: number;
  messages: Array<{
    name: string;
    kind: 'request' | 'reply';
    direction: 'both' | 'encode' | 'decode';
    wire: string;
    message: Json;
  }>;
  acceptance: Array<{
    name: string;
    kind: 'request' | 'reply' | 'bencode';
    accepted: boolean;
    used?: number;
    wire: WirePart[];
  }>;
  prices: Array<Record<'msat' | 'per_bytes' | 'min_msat' | 'bytes' | 'price_msat', string>>;
}

function hash(json: unknown): ContentHash {
  const { algorithm, digest } = json as { algorithm: ContentHash['algorithm']; digest: string };
  return { algorithm, digest: fromHex(digest) };
}

const int = (json: unknown): bigint => BigInt(json as string);
const bytes = (json: unknown): Uint8Array => fromHex(json as string);

function request(json: Json): Request {
  if (json.type === 'get') {
    return {
      type: 'get',
      hash: hash(json.hash),
      account: bytes(json.account),
      maxMsat: int(json.max_msat),
    };
  }
  expect(json.type).toBe('pay');
  return {
    type: 'pay',
    account: bytes(json.account),
    payment: bytes(json.payment),
    method: json.method as string,
    mint: json.mint as string,
    token: json.token as string,
  };
}

function reply(json: Json): Reply {
  switch (json.type) {
    case 'data':
      return {
        type: 'data',
        hash: hash(json.hash),
        chargedMsat: int(json.charged_msat),
        balanceMsat: int(json.balance_msat),
        duplicate: json.duplicate as boolean,
        data: bytes(json.data),
      };
    case 'quote': {
      const tariff = json.tariff as Json;
      return {
        type: 'quote',
        quote: {
          hash: hash(json.hash),
          size: int(json.size),
          priceMsat: int(json.price_msat),
          balanceMsat: int(json.balance_msat),
          graceMsat: int(json.grace_msat),
          tariff: {
            rate: { msat: int(tariff.msat), perBytes: int(tariff.per_bytes) },
            minMsat: int(tariff.min_msat),
          },
          mints: json.mints as string[],
          methods: json.methods as string[],
          minTopupSat: int(json.min_topup_sat),
        },
      };
    }
    case 'none':
      return { type: 'none', hash: hash(json.hash) };
    case 'paid':
      return {
        type: 'paid',
        payment: bytes(json.payment),
        creditedMsat: int(json.credited_msat),
        balanceMsat: int(json.balance_msat),
      };
    default: {
      expect(json.type).toBe('err');
      const base = { type: 'err' as const, code: json.code as never, detail: json.detail as string };
      return json.payment === null ? base : { ...base, payment: bytes(json.payment) };
    }
  }
}

function build(parts: WirePart[]): Uint8Array {
  const pieces = parts.map((part) => typeof part === 'string'
    ? fromHex(part)
    : new Uint8Array(part.times).fill(Number.parseInt(part.repeat, 16)));
  const out = new Uint8Array(pieces.reduce((total, piece) => total + piece.length, 0));
  let at = 0;
  for (const piece of pieces) {
    out.set(piece, at);
    at += piece.length;
  }
  return out;
}

describe('paid retrieval vectors shared with Rust', () => {
  it('uses the same names and limits', () => {
    expect(PROTOCOL).toBe(VECTORS.protocol);
    expect(BEP10_EXTENSION).toBe(VECTORS.bep10_extension);
    expect(METHOD_CASHU).toBe(VECTORS.method_cashu);
    expect(MAX_HEADER_BYTES).toBe(VECTORS.max_header_bytes);
    expect(MAX_MESSAGE_BYTES).toBe(VECTORS.max_message_bytes);
    expect(BLOB_MAX_BYTES).toBe(VECTORS.blob_max_bytes);
  });

  it('covers every kind of message', () => {
    const kinds = new Set(VECTORS.messages.map((vector) => `${vector.kind}:${vector.message.type}`));
    expect([...kinds].sort()).toEqual([
      'reply:data', 'reply:err', 'reply:none', 'reply:paid', 'reply:quote',
      'request:get', 'request:pay',
    ]);
    expect(VECTORS.acceptance.length).toBeGreaterThan(100);
  });

  for (const vector of VECTORS.messages) {
    it(`${vector.direction === 'both' ? 'encodes and decodes' : `${vector.direction}s`} ${vector.name}`, () => {
      const wire = fromHex(vector.wire);
      const message = vector.kind === 'request' ? request(vector.message) : reply(vector.message);
      if (vector.direction !== 'decode') {
        const encoded = vector.kind === 'request'
          ? encodeRequest(message as Request)
          : encodeReply(message as Reply);
        expect(toHex(encoded)).toBe(vector.wire);
      }
      const decoded = vector.kind === 'request' ? decodeRequest(wire) : decodeReply(wire);
      if (vector.direction === 'encode') expect(decoded).not.toEqual(message);
      else expect(decoded).toEqual(message);
    });
  }

  for (const vector of VECTORS.acceptance) {
    it(`${vector.accepted ? 'accepts' : 'rejects'} ${vector.name}`, () => {
      const wire = build(vector.wire);
      const decode = (): unknown => {
        if (vector.kind === 'bencode') return decodeBencodePrefix(wire).used;
        return vector.kind === 'request' ? decodeRequest(wire) : decodeReply(wire);
      };
      if (!vector.accepted) {
        expect(decode).toThrow();
      } else if (vector.kind === 'bencode') {
        expect(decode()).toBe(vector.used);
      } else {
        expect(decode).not.toThrow();
      }
    });
  }

  it('prices blobs the same way', () => {
    for (const price of VECTORS.prices) {
      const tariff = {
        rate: { msat: int(price.msat), perBytes: int(price.per_bytes) },
        minMsat: int(price.min_msat),
      };
      expect(priceMsat(tariff, int(price.bytes)), JSON.stringify(price)).toBe(int(price.price_msat));
    }
  });
});
